// Generates src/styles/tokens.css and src/styles/type.css from src/styles/tokens.figma.json,
// which is a dump of the Figma variables and text styles. Do not edit the CSS by hand.
//   node scripts/gen-tokens.mjs
import { readFileSync, writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const src = JSON.parse(readFileSync(join(root, "src/styles/tokens.figma.json"), "utf8"));
const header = "/* Generated by scripts/gen-tokens.mjs from tokens.figma.json. Do not edit. */\n";

const lines = [":root {"];
lines.push("  /* Primitives */");
for (const [name, hex] of Object.entries(src.primitives)) lines.push(`  ${name}: ${hex};`);
lines.push("", "  /* Color */");
for (const [name, alias] of Object.entries(src.color)) lines.push(`  ${name}: var(${alias});`);
lines.push("", "  /* Spacing, radius, layout, border */");
for (const [name, px] of Object.entries(src.dimension)) lines.push(`  ${name}: ${px}px;`);
lines.push("", "  /* Families */");
lines.push('  --font-sans: "Albert Sans", ui-sans-serif, system-ui, -apple-system, "Segoe UI", sans-serif;');
lines.push('  --font-mono: "JetBrains Mono", ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;');
lines.push("}");
writeFileSync(join(root, "src/styles/tokens.css"), `${header}${lines.join("\n")}\n`);

// Text styles become utility classes: Figma "Mono/Eyebrow" -> .text-mono-eyebrow
const type = [];
for (const [name, s] of Object.entries(src.textStyles)) {
  type.push(`.text-${name} {`);
  type.push(`  font-family: var(--font-${s.family});`);
  type.push(`  font-weight: ${s.weight};`);
  type.push(`  font-size: ${s.size}px;`);
  type.push(`  line-height: ${s.lineHeight}px;`);
  type.push(`  letter-spacing: ${s.letterSpacingPercent === 0 ? "0" : `${s.letterSpacingPercent / 100}em`};`);
  if (s.upper) type.push("  text-transform: uppercase;");
  type.push("}");
}
// Responsive pairs: the desktop style, switched to the Figma mobile style below 860 px (rules §4.9).
const responsive = {
  display: ["display-desktop", "display-mobile"],
  "heading-h2": ["heading-h2-desktop", "heading-h2-mobile"],
};
const decl = (s) =>
  `font-family: var(--font-${s.family}); font-weight: ${s.weight}; font-size: ${s.size}px; ` +
  `line-height: ${s.lineHeight}px; letter-spacing: ${s.letterSpacingPercent === 0 ? "0" : `${s.letterSpacingPercent / 100}em`};`;
for (const [name, [desktop, mobile]] of Object.entries(responsive)) {
  type.push(`.text-${name} { ${decl(src.textStyles[desktop])} }`);
  type.push(`@media (max-width: 859px) { .text-${name} { ${decl(src.textStyles[mobile])} } }`);
}
writeFileSync(join(root, "src/styles/type.css"), `${header}${type.join("\n")}\n`);
console.log("Wrote src/styles/tokens.css and src/styles/type.css");
